```json
{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT c.service_name AS client_svc, s.service_name AS server_svc, round(c.duration/1e6,1) AS client_ms, round(s.duration/1e6,1) AS server_ms, round(epoch_ms(s.time)-epoch_ms(c.time),1) AS start_offset_ms, round((epoch_ms(c.time)+c.duration/1e6)-(epoch_ms(s.time)+s.duration/1e6),1) AS end_gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='shipping' AND c.span_name='POST quote' ORDER BY c.time LIMIT 16", "claim": "shipping's outbound POST quote takes about 675ms, but quote receives it only after 675ms and responds in 0.3ms, with no return delay."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('shipping','quote') GROUP BY 1,2,3 ORDER BY 1,2", "claim": "shipping /get-quote server p95 rises to about 676ms while quote's own POST /getquote server span stays at 0.3ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, round(approx_quantile(duration,0.95)/1e6,1) p95_ms, count(*) n FROM normal_traces WHERE service_name='shipping' GROUP BY 1,2", "claim": "In the normal period shipping /get-quote p95 was about 1.9ms, so the delay is new."}
      ]
    },
    {
      "service": "frontend",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name LIKE 'dns%' GROUP BY 1,2,3,4", "claim": "Frontend dns.lookup client spans all end in Error (5 in abnormal) and none appear in the normal period."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE span_name LIKE '%api/product-reviews%' OR span_name LIKE '%product-ask-ai%' GROUP BY 1,2,3,4", "claim": "Product-review and AI-assistant user requests return HTTP 500 at frontend, with errors rising from 7 to 18 spans."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE (service_name='checkout' AND span_name IN ('HTTP POST','oteldemo.CheckoutService/PlaceOrder')) OR (service_name='shipping' AND span_name='/get-quote') GROUP BY 1,2,3", "claim": "Checkout's HTTP POST to shipping and its PlaceOrder server span both rise to about 680-700ms, matching shipping's slowdown."}
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY 1,2,3", "claim": "Frontend's POST /api/checkout p95 rises to about 710ms, inheriting checkout's wait on shipping."}
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name IN ('ingress','router frontend egress') GROUP BY 1,2,3,4", "claim": "Frontend-proxy ingress returns the 500s that frontend produces for product-review and AI-assistant requests."}
      ]
    }
  ]
}
